4	const STEP_MS = 100;
5	const IDLE_POLL_MS = 200;
6	const HEARTBEAT_MS = 1000;
7	const MAX_ATTEMPTS = 3;
8	
9	const db = openDatabase();
10	let stopping = false;
11	
12	for (const signal of ['SIGINT', 'SIGTERM'] as const) {
13	  process.on(signal, () => {
14	    stopping = true;
15	  });
16	}
17	
18	interface ClaimedJob {
19	  id: string;
20	  input: string;
21	  steps: number;
22	  fail_attempts: number;
23	  attempts: number;
24	}
25	
26	// Jobs left `running` by a worker that died are queued again; their interrupted attempt stays counted.
27	db.prepare("UPDATE jobs SET status = 'queued', run_after = 0, updated_at = ? WHERE status = 'running'").run(
28	  new Date().toISOString(),
29	);
30	
31	const beat = () =>
32	  db
33	    .prepare(
34	      "INSERT INTO heartbeats (name, at_ms) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at_ms = excluded.at_ms",
35	    )
36	    .run(Date.now());
37	beat();
38	const heartbeatTimer = setInterval(beat, HEARTBEAT_MS);
39	
40	const claimStmt = db.prepare(`
41	  UPDATE jobs
42	  SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ?
43	  WHERE seq = (
44	    SELECT seq FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1
45	  )
46	  RETURNING id, input, steps, fail_attempts, attempts`);
47	
48	function claim(): ClaimedJob | undefined {
49	  const now = Date.now();
50	  return claimStmt.get(new Date(now).toISOString(), now) as unknown as ClaimedJob | undefined;
51	}
52	
53	function setProgress(id: string, completed: number): void {
54	  db.prepare('UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ?').run(completed, new Date().toISOString(), id);
55	}
56	
57	function finishCompleted(job: ClaimedJob): void {
58	  db.prepare(
59	    `UPDATE jobs SET status = 'completed', completed = steps, output = ?, error = NULL, updated_at = ? WHERE id = ?`,
60	  ).run(job.input.toUpperCase(), new Date().toISOString(), job.id);
61	}
62	
63	function finishFailed(job: ClaimedJob): void {
64	  db.prepare(`UPDATE jobs SET status = 'failed', error = 'transient failure', output = NULL, updated_at = ? WHERE id = ?`).run(
65	    new Date().toISOString(),
66	    job.id,
67	  );
68	}
69	
70	function requeue(job: ClaimedJob): void {
71	  const delay = 250 + Math.floor(Math.random() * 1751); // 250..2000 ms
72	  db.prepare(`UPDATE jobs SET status = 'queued', run_after = ?, updated_at = ? WHERE id = ?`).run(
73	    Date.now() + delay,
74	    new Date().toISOString(),
75	    job.id,
76	  );
77	}
78	
79	/** Runs one attempt. Returns early without changing the job if the worker is stopping. */
80	async function runAttempt(job: ClaimedJob): Promise<void> {
81	  if (job.attempts <= job.fail_attempts) {
82	    await sleep(STEP_MS);
83	    if (stopping) return;
84	    if (job.attempts >= MAX_ATTEMPTS) finishFailed(job);
85	    else requeue(job);
